//! Known answers from the extracted spec, not a capture generated by this implementation.

use ftx_measure::{
    NAMES, age_from_stature, cdc_stature, fuse, fused_value, make_record, priors_for,
    reference_wearer, unit,
};
use serde_json::{Value, json};

#[test]
fn all_reference_records_match_d2_values_bounds_and_methods() {
    let spec = include_str!("../../../docs/spec/02-drafting-body-measurements.md");
    let section = spec
        .split("### D.2 Fixture:")
        .nth(1)
        .unwrap()
        .split("`priors_for(920, 30)`")
        .next()
        .unwrap();
    let wearer = reference_wearer(920.0, Some(30.0), None, None).unwrap();
    assert_eq!(wearer["records"].as_array().unwrap().len(), 35);
    let mut count = 0;
    for line in section.lines().filter(|s| s.starts_with("| `")) {
        let cols: Vec<&str> = line.trim_matches('|').split('|').map(str::trim).collect();
        let name = cols[0].trim_matches('`');
        let u = unit(name);
        let record = &wearer["records"][count];
        assert_eq!(record["name"], name);
        for (key, col) in [
            (format!("value_{u}"), 1),
            (format!("sigma_{u}"), 2),
            (format!("p3_p97_{u}"), 3),
            (format!("p1_p99_{u}"), 4),
        ] {
            let expected: Value = serde_json::from_str(cols[col]).unwrap();
            if let Some(a) = expected.as_array() {
                let expected: Vec<f64> = a.iter().map(|v| v.as_f64().unwrap()).collect();
                let actual: Vec<f64> = record[&key]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_f64().unwrap())
                    .collect();
                assert_eq!(actual, expected, "{name} {key}");
            } else {
                assert_eq!(record[&key].as_f64(), expected.as_f64(), "{name} {key}");
            }
        }
        assert_eq!(record["method"], cols[5], "{name} method");
        assert_eq!(wearer["fused"][name]["flags"], json!(["PRIOR_ONLY"]));
        count += 1;
    }
    assert_eq!(count, 35);
    assert_eq!(
        wearer["fusion"]["stature_source"],
        "stature CHART_PRIOR record"
    );
    assert_eq!(wearer["fusion"]["stature_for_priors_mm"], 920.0);
    assert_eq!(wearer["wearer"]["label"], "reference toddler 92 cm");
}

#[test]
fn chart_conditioning_and_coverage() {
    let (median, sd) = cdc_stature(30.0, None).unwrap();
    assert!((median - 904.125).abs() < 1e-10);
    assert!((sd - 37.462).abs() < 0.001);
    assert!((age_from_stature(920.0).unwrap() - 32.32).abs() < 0.01);
    let p = priors_for(920.0, None, None).unwrap();
    assert_eq!(p.as_object().unwrap().len(), 34);
    assert!(p.get("stature").is_none());
    assert_eq!(p["head"]["value_mm"], 486.2);
    assert!(
        p["head"]["notes"]
            .as_str()
            .unwrap()
            .contains("age inferred")
    );
    let p = priors_for(920.0, Some(30.0), None).unwrap();
    assert_eq!(p["stature"]["value_mm"], 904.1);
    assert_eq!(p["stature"]["p1_p99_mm"], json!([817.0, 991.3]));
    for h in [800.0, 860.0, 920.0, 1040.0, 1160.0, 1280.0] {
        for age in [18.0, 30.0, 48.0, 72.0, 90.0] {
            let p = priors_for(h, Some(age), Some("F")).unwrap();
            for name in NAMES {
                assert!(p[name][format!("sigma_{}", unit(name))].as_f64().unwrap() > 0.0);
            }
        }
    }
    for h in [799.9, 1280.1, f64::NAN, f64::INFINITY] {
        assert!(priors_for(h, None, None).is_err());
    }
    assert!(priors_for(920.0, Some(f64::NAN), None).is_err());
    assert_eq!(
        cdc_stature(30.0, Some("boy")).unwrap(),
        cdc_stature(30.0, Some("M")).unwrap()
    );
}

fn record(name: &str, value: f64, sigma: f64, source: &str) -> Value {
    make_record(name, value, sigma, source, source, None, "").unwrap()
}
fn data(records: Vec<Value>) -> Value {
    json!({"schema":"fabric-measurements/1","wearer":{"stature_mm":920.0,"age_months":30.0},"records":records,"fused":{}})
}

#[test]
fn whole_file_fusion_recomputes_and_preserves_evidence_without_priors() {
    let mut input = data(vec![
        record("chest", 550.0, 10.0, "MEASURED_TAPE"),
        record("chest", 570.0, 20.0, "PHOTO_ESTIMATED"),
    ]);
    input["fused"] = json!({"chest":{"value_mm":9999,"sigma_mm":0}});
    let f = fuse(&input, false).unwrap();
    assert_eq!(fused_value(&f, "bust"), Some((554.0, 8.9)));
    assert_eq!(f["fused"]["chest"]["sources"][2]["used"], false);
    assert_eq!(f["fused"]["chest"]["sources"][2]["auto_prior"], true);
    assert!(f["fused"].get("hip").is_none());
    assert_eq!(f["fusion"]["priors_used"], false);
    assert_eq!(fused_value(&f, "height"), Some((920.0, 10.0)));
    assert_eq!(input["fused"]["chest"]["value_mm"], 9999);
    let f = fuse(
        &data(vec![record("chest", 550.0, 10.0, "MEASURED_TAPE")]),
        true,
    )
    .unwrap();
    assert_eq!(fused_value(&f, "chest"), Some((549.0, 9.5)));
    assert_eq!(f["fused"]["hip"]["flags"], json!(["PRIOR_ONLY"]));
}

#[test]
fn normalization_exclusion_unknown_names_and_outside_chart() {
    let mut waist = record("waist", 500.0, 15.0, "MEASURED_TAPE");
    waist["definition_id"] = json!("CPSC77:66-navel");
    let mut incompatible = record("inseam", 330.0, 20.0, "MEASURED_TAPE");
    incompatible["definition_id"] = json!("other-level");
    let mut d = data(vec![
        waist,
        incompatible,
        record("custom-length", 42.0, 5.0, "MEASURED_TAPE"),
    ]);
    let f = fuse(&d, false).unwrap();
    assert_eq!(fused_value(&f, "waist"), Some((490.0, 15.8)));
    assert_eq!(
        f["fused"]["waist"]["flags"],
        json!(["NORMALIZED_DEFINITION"])
    );
    assert_eq!(
        f["fused"]["custom_length"]["flags"],
        json!(["NOT_IN_CATALOGUE"])
    );
    assert_eq!(
        f["fusion"]["excluded"]["inseam"].as_array().unwrap().len(),
        1
    );
    let f = fuse(&d, true).unwrap();
    assert_eq!(
        f["fused"]["inseam"]["flags"],
        json!(["PRIOR_ONLY", "UNNORMALIZED_EXCLUDED"])
    );
    d["wearer"]["stature_mm"] = json!(1800);
    let f = fuse(&d, true).unwrap();
    assert!(!f["fusion"]["notes"].as_array().unwrap().is_empty());
    assert_eq!(fused_value(&f, "custom_length"), Some((42.0, 5.0)));
    assert_eq!(f["fusion"]["priors_used"], false);
}

#[test]
fn user_prior_and_measured_stature_precedence() {
    let d = data(vec![
        record("stature", 1000.0, 10.0, "MEASURED_TAPE"),
        record("chest", 777.0, 12.0, "CHART_PRIOR"),
    ]);
    let f = fuse(&d, false).unwrap();
    assert_eq!(f["fusion"]["stature_for_priors_mm"], 1000.0);
    assert_eq!(fused_value(&f, "chest"), Some((777.0, 12.0)));
    assert_eq!(f["fused"]["chest"]["flags"], json!(["PRIOR_ONLY"]));
    let mut no_height = data(vec![]);
    no_height["wearer"] = json!({});
    let f = fuse(&no_height, true).unwrap();
    assert_eq!(f["fused"], json!({}));
    assert_eq!(f["fusion"]["stature_source"], "none");
}

#[test]
fn all_five_d6_size_columns_match() {
    let spec = include_str!("../../../docs/spec/02-drafting-body-measurements.md");
    let section = spec
        .split("### D.6 Fixture:")
        .nth(1)
        .unwrap()
        .split("\n### ")
        .next()
        .unwrap();
    let priors: Vec<Value> = [
        (800.0, 15.0),
        (920.0, 30.0),
        (980.0, 36.0),
        (1040.0, 48.0),
        (1160.0, 72.0),
    ]
    .into_iter()
    .map(|(h, a)| priors_for(h, Some(a), None).unwrap())
    .collect();
    let mut count = 0;
    for line in section.lines().filter(|s| s.starts_with("| `")) {
        let cols: Vec<&str> = line.trim_matches('|').split('|').map(str::trim).collect();
        if cols.len() != 6 {
            continue;
        }
        let name = cols[0].trim_matches('`');
        if !NAMES.contains(&name) {
            continue;
        }
        for (i, p) in priors.iter().enumerate() {
            let (v, s) = cols[i + 1].split_once('±').unwrap();
            assert_eq!(
                p[name][format!("value_{}", unit(name))].as_f64().unwrap(),
                v.trim().parse::<f64>().unwrap(),
                "{name} column {i} value"
            );
            assert_eq!(
                p[name][format!("sigma_{}", unit(name))].as_f64().unwrap(),
                s.trim().parse::<f64>().unwrap(),
                "{name} column {i} sigma"
            );
        }
        count += 1;
    }
    assert_eq!(count, 35);
}
